import{_ as n,o as i,c as r,a2 as t}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"SOLID设计原则","description":"","frontmatter":{},"headers":[],"relativePath":"理论/SOLID设计原则/SOLID设计原则.md","filePath":"理论/SOLID设计原则/SOLID设计原则.md","lastUpdated":1767864420000}'),o={name:"理论/SOLID设计原则/SOLID设计原则.md"};function a(p,e,s,l,c,d){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="solid设计原则" tabindex="-1">SOLID设计原则 <a class="header-anchor" href="#solid设计原则" aria-label="Permalink to &quot;SOLID设计原则&quot;">​</a></h1><p>SOLID原则是面向对象设计（OOD）领域的核心设计原则集合，由罗伯特·C·马丁（Robert C. Martin，昵称“鲍勃大叔”）提出。其目的是提升代码的可维护性、可扩展性和可读性，降低系统迭代过程中的修改成本。</p><h2 id="一、单一职责原则-single-responsibility-principle-srp" tabindex="-1">一、单一职责原则（Single Responsibility Principle, SRP） <a class="header-anchor" href="#一、单一职责原则-single-responsibility-principle-srp" aria-label="Permalink to &quot;一、单一职责原则（Single Responsibility Principle, SRP）&quot;">​</a></h2><p><strong>核心定义</strong>：一个类应该只有一个引起它变化的原因，即一个类只负责一项核心职责。</p><p><strong>关键逻辑</strong>：若一个类承担多个职责，当其中一个职责需要修改时，可能会影响到其他职责的正常运行，增加代码的耦合度和出错风险。</p><p><strong>实践启示</strong>：拆分“万能类”，将不同职责封装到独立的类中。例如，将“用户数据存储”和“用户信息验证”拆分为两个类，而非合并在一个“用户管理类”中。</p><h2 id="二、开放-封闭原则-open-closed-principle-ocp" tabindex="-1">二、开放/封闭原则（Open/Closed Principle, OCP） <a class="header-anchor" href="#二、开放-封闭原则-open-closed-principle-ocp" aria-label="Permalink to &quot;二、开放/封闭原则（Open/Closed Principle, OCP）&quot;">​</a></h2><p><strong>核心定义</strong>：软件实体（类、模块、函数等）应该对扩展开放，对修改关闭。</p><p><strong>关键逻辑</strong>：通过扩展现有代码来实现新功能，而非修改已有功能的核心代码，从而避免破坏原有系统的稳定性。</p><p><strong>实践启示</strong>：依赖抽象（如接口、抽象类）而非具体实现。例如，定义“支付接口”，新增“支付宝支付”“微信支付”时，只需新增实现类实现接口，无需修改原有支付逻辑代码。</p><h2 id="三、里氏替换原则-liskov-substitution-principle-lsp" tabindex="-1">三、里氏替换原则（Liskov Substitution Principle, LSP） <a class="header-anchor" href="#三、里氏替换原则-liskov-substitution-principle-lsp" aria-label="Permalink to &quot;三、里氏替换原则（Liskov Substitution Principle, LSP）&quot;">​</a></h2><p><strong>核心定义</strong>：子类对象必须能够替换其基类对象，且替换后系统的行为保持不变。</p><p><strong>关键逻辑</strong>：子类继承基类时，应遵循基类的行为契约，不破坏原有逻辑。即“哪里需要基类，哪里就可以用子类”。</p><p><strong>实践启示</strong>：避免子类重写基类的核心方法后导致逻辑异常。例如，“正方形”不应继承“长方形”，因为修改正方形的“宽”会同时改变“长”，破坏长方形“长和宽独立修改”的行为契约。</p><h2 id="四、接口隔离原则-interface-segregation-principle-isp" tabindex="-1">四、接口隔离原则（Interface Segregation Principle, ISP） <a class="header-anchor" href="#四、接口隔离原则-interface-segregation-principle-isp" aria-label="Permalink to &quot;四、接口隔离原则（Interface Segregation Principle, ISP）&quot;">​</a></h2><p><strong>核心定义</strong>：客户端不应该依赖它不需要的接口，即一个大接口应拆分为多个小而具体的接口，避免“胖接口”。</p><p><strong>关键逻辑</strong>：若一个接口包含客户端不需要的方法，客户端被迫实现这些无用方法，既增加冗余代码，又会因接口修改而受到不必要的影响。</p><p><strong>实践启示</strong>：按功能拆分接口。例如，将“动物接口”拆分为“会飞接口”“会跑接口”“会游接口”，让“鸟”实现“会飞+会跑”接口，“鱼”实现“会游”接口，而非让所有动物都实现包含所有方法的“动物接口”。</p><h2 id="五、依赖倒置原则-dependency-inversion-principle-dip" tabindex="-1">五、依赖倒置原则（Dependency Inversion Principle, DIP） <a class="header-anchor" href="#五、依赖倒置原则-dependency-inversion-principle-dip" aria-label="Permalink to &quot;五、依赖倒置原则（Dependency Inversion Principle, DIP）&quot;">​</a></h2><p><strong>核心定义</strong>：高层模块不应该依赖低层模块，两者都应该依赖抽象；抽象不应该依赖细节，细节应该依赖抽象。</p><p><strong>关键逻辑</strong>：通过抽象（接口、抽象类）建立高层与低层模块的联系，降低两者的直接耦合。高层模块定义业务逻辑，低层模块提供具体实现，抽象层隔离变化。</p><p><strong>实践启示</strong>：采用“依赖注入”等方式注入抽象依赖。例如，高层模块“订单服务”依赖“支付抽象接口”，而非直接依赖低层的“支付宝支付类”“微信支付类”，新增支付方式时只需替换注入的实现类即可。</p><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>SOLID原则的核心是“解耦”与“抗变”：单一职责、接口隔离聚焦“职责拆分”，减少耦合；开放/封闭、里氏替换聚焦“扩展兼容”，应对变化；依赖倒置则通过“抽象依赖”串联各原则，形成整体设计思路。实践中无需机械套用，需结合业务场景灵活运用，平衡设计复杂度与业务需求。</p><blockquote><p>（注：文档部分内容可能由 AI 生成）</p></blockquote>',25)])])}const P=n(o,[["render",a]]);export{h as __pageData,P as default};
